# ===== BEGIN FILE: tmp/tests/cellsim.py =====
"""cellsim: capacity model of a multi-LoRA inference cell.

This is the planning model the inference platform uses to check a placement plan against a
request trace before it is rolled out. It is deliberately coarse in time (one-minute steps) and
exact in cache behaviour:

  * Router: an adapter's requests are spread round-robin over the workers in its worker set.
    Adapters without an entry in the plan are routed to a single worker picked by rendezvous
    hashing on the adapter id. The router's affinity table has a fixed number of
    adapter->worker entries (cell.json: router.max_affinity_entries).
  * GPU LoRA pool (per worker): pinned adapters stay resident; the rest of the pool is an LRU
    cache. A request for an adapter that is not resident triggers a load.
  * Host adapter cache (per node): staged adapters are always in host memory; the rest of the
    host cache is an LRU cache in front of the object store. Loads from host memory are fast;
    loads from the object store pay first-byte latency and share the node's pull bandwidth with
    every other object-store load on that node in the same minute.
  * Compute: per worker and minute, interactive work is served first; batch-priority work uses
    leftover capacity and adds some interference. Overload carries over as backlog.
  * TTFT for an interactive request = prefill (slower when busy) + backlog + queueing wait
    (exponential tail, mean grows with utilisation) + adapter load delay when it arrives while
    its adapter is loading.

All quantities that matter for capacity planning are in cell.json.
"""
import hashlib
import json
from collections import OrderedDict

import numpy as np
import scipy.sparse as sp


# ----------------------------------------------------------------------------- config
class Cell:
    def __init__(self, cfg):
        self.cfg = cfg
        self.workers = list(cfg["workers"])
        self.R = len(self.workers)
        self.widx = {w: i for i, w in enumerate(self.workers)}
        self.node_names = sorted(cfg["nodes"])
        self.node_of = np.zeros(self.R, np.int64)
        for n, ws in cfg["nodes"].items():
            for w in ws:
                self.node_of[self.widx[w]] = self.node_names.index(n)
        self.N = len(self.node_names)
        m = cfg["memory"]
        self.pool = float(m["lora_pool_bytes_per_worker"])
        self.min_ondemand = float(m["min_on_demand_bytes_per_worker"])
        self.host = float(m["host_adapter_cache_bytes_per_node"])
        p = cfg["profile"]
        self.prefill_tps = float(p["prefill_tokens_per_s"])
        self.decode_tps = float(p["decode_tokens_per_s"])
        self.ttft_fixed = float(p["ttft_fixed_s"])
        self.prefill_slow = float(p["prefill_slowdown_at_full_load"])
        self.mlora = float(p["multi_lora_overhead_per_log_adapter"])
        self.batch_intf = float(p["batch_interference"])
        self.wait_scale = float(p["queue_wait_scale_s"])
        self.rho_cap = float(p.get("utilisation_cap", 0.97))
        o = cfg["adapter_loading"]
        self.os_first = float(o["object_store_first_byte_s"])
        self.os_bw = float(o["object_store_node_bandwidth_Bps"])
        self.register = float(o["gpu_register_s"])
        self.h2d_bw = float(o["host_to_gpu_bandwidth_Bps"])
        self.h2d_fixed = float(o["host_to_gpu_fixed_s"])
        self.slo = {k: float(v) for k, v in cfg["slo_ttft_s"].items()}
        self.max_affinity = int(cfg["router"]["max_affinity_entries"])

    @classmethod
    def load(cls, path):
        with open(path) as f:
            return cls(json.load(f))


def rendezvous_worker(adapter_ids, workers):
    """Default worker for adapters that are not in the plan (highest-random-weight hashing)."""
    out = np.zeros(len(adapter_ids), np.int64)
    for i, a in enumerate(adapter_ids):
        best, bi = -1, 0
        for j, w in enumerate(workers):
            h = int.from_bytes(hashlib.blake2b(f"{a}|{w}".encode(), digest_size=8).digest(), "big")
            if h > best:
                best, bi = h, j
        out[i] = bi
    return out


class Adapters:
    """Per-adapter attributes, indexed 0..A-1 (index = position in `ids`)."""
    def __init__(self, ids, size_bytes, prompt_tokens, output_tokens, premium, batch, cell):
        self.ids = list(ids)
        self.index = {a: i for i, a in enumerate(self.ids)}
        self.A = len(self.ids)
        self.bytes = np.asarray(size_bytes, np.int64)
        self.prompt = np.asarray(prompt_tokens, float)
        self.output = np.asarray(output_tokens, float)
        self.premium = np.asarray(premium, bool)
        self.batch = np.asarray(batch, bool)
        self.work = self.prompt / cell.prefill_tps + self.output / cell.decode_tps
        self.prefill = self.prompt / cell.prefill_tps + cell.ttft_fixed
        self.default_worker = rendezvous_worker(self.ids, cell.workers)


# ----------------------------------------------------------------------------- plan
class Plan:
    """sets[i]: list of worker indices ([] = default routing); pinned / staged: bool arrays."""
    def __init__(self, A):
        self.sets = [[] for _ in range(A)]
        self.pinned = np.zeros(A, bool)
        self.staged = np.zeros(A, bool)

    def resolved(self, adapters):
        d = adapters.default_worker
        return [s if len(s) else [int(d[i])] for i, s in enumerate(self.sets)]

    def usage(self, adapters, cell):
        sets = self.resolved(adapters)
        pin = np.zeros(cell.R)
        stage = np.zeros(cell.N)
        for i in np.nonzero(self.pinned)[0]:
            pin[sets[i]] += adapters.bytes[i]
        for i in np.nonzero(self.staged)[0]:
            for n in set(cell.node_of[sets[i]].tolist()):
                stage[n] += adapters.bytes[i]
        return pin, stage

    def violations(self, adapters, cell):
        pin, stage = self.usage(adapters, cell)
        errs = []
        lim = cell.pool - cell.min_ondemand
        for r in np.nonzero(pin > lim)[0]:
            errs.append(f"worker {cell.workers[r]}: pinned {int(pin[r])} B > {int(lim)} B")
        for n in np.nonzero(stage > cell.host)[0]:
            errs.append(f"node {cell.node_names[n]}: staged {int(stage[n])} B > {int(cell.host)} B")
        entries = sum(len(x) for x in self.sets)
        if entries > cell.max_affinity:
            errs.append(f"router affinity table: {entries} adapter->worker entries > {cell.max_affinity}")
        return errs

    def to_json(self, adapters, cell, meta=None):
        rows = []
        for i in range(adapters.A):
            if not self.sets[i] and not self.pinned[i] and not self.staged[i]:
                continue
            rows.append({"adapter_id": adapters.ids[i],
                         "workers": [cell.workers[r] for r in (self.sets[i] or [int(adapters.default_worker[i])])],
                         "pin_gpu": bool(self.pinned[i]), "stage_host": bool(self.staged[i])})
        d = dict(meta or {})
        d["adapters"] = rows
        return d


class PlanError(Exception):
    pass


MAX_PLAN_BYTES = 32 * 1024 * 1024


def parse_plan(obj, adapters, cell, allowed=None):
    """Parse a plan document (already json-decoded). Raises PlanError on schema problems.
    `allowed`: optional set of adapter ids that may appear in a plan (registered adapters)."""
    if not isinstance(obj, dict) or not isinstance(obj.get("adapters"), list):
        raise PlanError("plan must be an object with an 'adapters' list")
    plan = Plan(adapters.A)
    seen = set()
    for k, e in enumerate(obj["adapters"]):
        if not isinstance(e, dict):
            raise PlanError(f"entry {k}: not an object")
        a = e.get("adapter_id")
        if not isinstance(a, str) or a not in adapters.index or (allowed is not None and a not in allowed):
            raise PlanError(f"entry {k}: unknown adapter_id {a!r}")
        if a in seen:
            raise PlanError(f"entry {k}: duplicate adapter_id {a}")
        seen.add(a)
        i = adapters.index[a]
        ws = e.get("workers", [])
        if not isinstance(ws, list) or not all(isinstance(w, str) for w in ws):
            raise PlanError(f"{a}: workers must be a list of worker names")
        if len(set(ws)) != len(ws):
            raise PlanError(f"{a}: duplicate workers")
        try:
            plan.sets[i] = sorted(cell.widx[w] for w in ws)
        except KeyError as ex:
            raise PlanError(f"{a}: unknown worker {ex}")
        for key, arr in (("pin_gpu", plan.pinned), ("stage_host", plan.staged)):
            v = e.get(key, False)
            if not isinstance(v, bool):
                raise PlanError(f"{a}: {key} must be true/false")
            arr[i] = v
    return plan


# ----------------------------------------------------------------------------- traces
def trace_from_arrays(minute, adapter, count, T):
    """CSR-by-minute trace from (minute, adapter_index, count) rows."""
    minute = np.asarray(minute, np.int64); adapter = np.asarray(adapter, np.int64)
    count = np.asarray(count, np.int64)
    ok = (minute >= 0) & (minute < T) & (count > 0)
    minute, adapter, count = minute[ok], adapter[ok], count[ok]
    o = np.lexsort((adapter, minute))
    minute, adapter, count = minute[o], adapter[o], count[o]
    # merge duplicate (minute, adapter) rows
    key = minute * (adapter.max() + 1 if len(adapter) else 1) + adapter
    u, first = np.unique(key, return_index=True)
    count = np.add.reduceat(count, first) if len(first) else count
    minute, adapter = minute[first], adapter[first]
    indptr = np.zeros(T + 1, np.int64)
    np.add.at(indptr, minute + 1, 1)
    return dict(indptr=np.cumsum(indptr), adapter=adapter, count=count)


# ----------------------------------------------------------------------------- simulation
def simulate(trace, adapters, plan, cell, minute0=0, period_len=7 * 1440, detail=False):
    """Replay `trace` against `plan`. Returns dashboard metrics per (tier, period).

    period index = (minute0 + minute) // period_len, i.e. pass the minute offset of the trace
    start relative to the start of a week to get per-week numbers.
    """
    R, N = cell.R, cell.N
    node_of = cell.node_of
    ip, aa, cc = trace["indptr"], trace["adapter"], trace["count"]
    T = len(ip) - 1
    A = adapters.A
    sets = plan.resolved(adapters)
    k = np.array([len(s) for s in sets])
    setarr = [np.asarray(s, np.int64) for s in sets]
    flat = np.concatenate(setarr)
    rows = np.repeat(np.arange(A), k)
    Wm = sp.csr_matrix((1.0 / k[rows], (rows, flat)), shape=(A, R))
    Wb = sp.csr_matrix((np.ones(len(flat)), (rows, flat)), shape=(A, R))
    isb = adapters.batch[aa]
    wk = cc * adapters.work[aa]
    Ci = sp.csr_matrix((np.where(isb, 0.0, wk), aa, ip), shape=(T, A))
    Cb = sp.csr_matrix((np.where(isb, wk, 0.0), aa, ip), shape=(T, A))
    Cn = sp.csr_matrix((np.ones(len(aa)), aa, ip), shape=(T, A))
    I = np.asarray((Ci @ Wm).todense())
    B = np.asarray((Cb @ Wm).todense())
    D = np.asarray((Cn @ Wb).todense())
    hf = 1 + cell.mlora * np.log1p(D)
    I *= hf; B *= hf
    Q = np.zeros((T, R)); rho = np.zeros((T, R))
    q = np.zeros(R); qb = np.zeros(R)
    for t in range(T):
        Q[t] = q
        cap_left = np.maximum(0.0, 60.0 - (q + I[t]))
        bserved = np.minimum(cap_left, qb + B[t])
        qb = qb + B[t] - bserved
        rho[t] = np.minimum(cell.rho_cap, (np.minimum(I[t] + q, 60.0) + cell.batch_intf * bserved) / 60.0)
        q = np.maximum(0.0, q + I[t] - 60.0)
    # ---- adapter caches
    pinned, staged = plan.pinned, plan.staged
    gpu_cap = np.full(R, cell.pool)
    for i in np.nonzero(pinned)[0]:
        gpu_cap[setarr[i]] -= adapters.bytes[i]
    host_cap = np.full(N, cell.host)
    host_staged = [set() for _ in range(N)]
    for i in np.nonzero(staged)[0]:
        for n in set(node_of[setarr[i]].tolist()):
            host_staged[n].add(int(i)); host_cap[n] -= adapters.bytes[i]
    gpu = [OrderedDict() for _ in range(R)]
    gpu_used = np.zeros(R)
    host = [OrderedDict() for _ in range(N)]
    host_used = np.zeros(N)
    ptr = np.zeros(A, np.int64)
    by = adapters.bytes
    unp = ~pinned
    multi = (k > 1).tolist()
    single = [int(s[0]) for s in setarr]
    nodel = node_of.tolist()
    cold_t, cold_i, cold_r, cold_src = [], [], [], []
    for t in range(T):
        s0, s1 = ip[t], ip[t + 1]
        if s0 == s1:
            continue
        ids = aa[s0:s1]; cnts = cc[s0:s1]
        sel = unp[ids]
        for i, n in zip(ids[sel].tolist(), cnts[sel].tolist()):
            if multi[i]:
                s = setarr[i]; kk = len(s)
                if n >= kk:
                    reps = s.tolist()
                else:
                    p = ptr[i]
                    reps = [int(s[(p + j) % kk]) for j in range(n)]
                ptr[i] = (ptr[i] + n) % kk
            else:
                reps = (single[i],)
            b = int(by[i])
            for r in reps:
                cache = gpu[r]
                if i in cache:
                    cache.move_to_end(i)
                    continue
                nd = nodel[r]
                if i in host_staged[nd]:
                    src = 1
                else:
                    hc = host[nd]
                    if i in hc:
                        hc.move_to_end(i); src = 1
                    else:
                        src = 2
                        if b <= host_cap[nd]:
                            while host_used[nd] + b > host_cap[nd] and hc:
                                _, eb = hc.popitem(last=False); host_used[nd] -= eb
                            hc[i] = b; host_used[nd] += b
                while gpu_used[r] + b > gpu_cap[r] and cache:
                    _, eb = cache.popitem(last=False); gpu_used[r] -= eb
                if b <= gpu_cap[r]:
                    cache[i] = b; gpu_used[r] += b
                cold_t.append(t); cold_i.append(i); cold_r.append(r); cold_src.append(src)
    cold_t = np.asarray(cold_t, np.int64); cold_i = np.asarray(cold_i, np.int64)
    cold_r = np.asarray(cold_r, np.int64); cold_src = np.asarray(cold_src, np.int64)
    sz = by[cold_i].astype(float)
    remote = cold_src == 2
    key = cold_t * N + node_of[cold_r]
    tot_remote = np.bincount(key[remote], weights=sz[remote], minlength=T * N) if remote.any() else np.zeros(T * N)
    L = np.where(remote, cell.os_first + (sz + 0.5 * (tot_remote[key] - sz)) / cell.os_bw + cell.register,
                 cell.h2d_fixed + sz / cell.h2d_bw)
    # ---- per (minute, adapter, worker) interactive request groups, one day at a time
    ckey = (cold_t * A + cold_i) * R + cold_r
    oc = np.argsort(ckey)
    ckey_s, L_s, S_s = ckey[oc], L[oc], cold_src[oc]
    off = np.concatenate([[0], np.cumsum(k)])
    single_a = np.asarray(single)
    p_first = minute0 // period_len
    n_per = int((minute0 + T - 1) // period_len - p_first + 1) if T else 0
    acc = np.zeros((n_per, 2, 3))           # period x tier (0 = premium) x (requests, misses, load misses)
    if detail:
        cold_cost = np.zeros(A * R); remote_cost = np.zeros(A * N)
        miss_a = np.zeros(A); coldmiss_a = np.zeros(A); req_a = np.zeros(A)
    CH = 1440
    for c0 in range(0, T, CH):
        c1 = min(T, c0 + CH)
        s0, s1 = ip[c0], ip[c1]
        if s0 == s1:
            continue
        a_ = aa[s0:s1]; n_ = cc[s0:s1]
        t_ = np.repeat(np.arange(c0, c1), np.diff(ip[c0:c1 + 1]))
        inter = ~adapters.batch[a_]
        m1 = inter & (k[a_] == 1)
        gt = [t_[m1]]; gi = [a_[m1]]; gr = [single_a[a_[m1]]]; gn = [n_[m1].astype(float)]
        mm = np.nonzero(inter & (k[a_] > 1))[0]
        if len(mm):
            kk = k[a_[mm]]
            rep = np.repeat(mm, kk)
            within = np.arange(len(rep)) - np.repeat(np.cumsum(kk) - kk, kk)
            gt.append(t_[rep]); gi.append(a_[rep]); gr.append(flat[off[a_[rep]] + within])
            gn.append(n_[rep] / k[a_[rep]])
        gt = np.concatenate(gt); gi = np.concatenate(gi); gr = np.concatenate(gr); gn = np.concatenate(gn)
        Lg = np.zeros(len(gt)); Sg = np.zeros(len(gt), np.int64)
        if len(ckey_s) and len(gt):
            gkey = (gt * A + gi) * R + gr
            pos = np.minimum(np.searchsorted(ckey_s, gkey), len(ckey_s) - 1)
            hit = ckey_s[pos] == gkey
            Lg[hit] = L_s[pos[hit]]; Sg[hit] = S_s[pos[hit]]
        rh = rho[gt, gr]; Qg = Q[gt, gr]
        pre = adapters.prefill[gi] * (1 + cell.prefill_slow * rh)
        Wq = cell.wait_scale * rh / (1 - rh)
        prem = adapters.premium[gi]
        slo = np.where(prem, cell.slo["premium"], cell.slo["standard"])
        slack = slo - pre - Qg
        qmiss = np.where(slack <= 0, 1.0, np.exp(-np.maximum(slack, 0) / np.maximum(Wq, 1e-3)))
        coldm = np.where(Lg > 0, (Lg > slack).astype(float) + np.maximum(gn - 1, 0) * np.clip((Lg - slack) / 60.0, 0, 1), 0.0)
        coldm = np.minimum(coldm, gn)
        cm = (1 - qmiss) * coldm
        miss = gn * qmiss + cm
        b = ((minute0 + gt) // period_len - p_first) * 2 + (~prem).astype(np.int64)
        acc[:, :, 0] += np.bincount(b, weights=gn, minlength=n_per * 2).reshape(n_per, 2)
        acc[:, :, 1] += np.bincount(b, weights=miss, minlength=n_per * 2).reshape(n_per, 2)
        acc[:, :, 2] += np.bincount(b, weights=cm, minlength=n_per * 2).reshape(n_per, 2)
        if detail:
            cold_cost += np.bincount(gi * R + gr, weights=cm, minlength=A * R)
            rm = Sg == 2
            remote_cost += np.bincount(gi[rm] * N + node_of[gr[rm]], weights=cm[rm], minlength=A * N)
            miss_a += np.bincount(gi, weights=miss, minlength=A)
            coldmiss_a += np.bincount(gi, weights=cm, minlength=A)
            req_a += np.bincount(gi, weights=gn, minlength=A)
    out = {"periods": {}}
    for j in range(n_per):
        d = {}
        for ti, tier in enumerate(("premium", "standard")):
            n, x, l = acc[j, ti]
            d[tier] = dict(requests=float(n), ttft_slo_misses=float(x),
                           ttft_slo_miss_rate=float(x / n) if n else 0.0, load_delay_misses=float(l))
        out["periods"][int(p_first + j)] = d
    out["adapter_loads"] = int(len(cold_t))
    out["object_store_loads"] = int(remote.sum())
    out["worker_utilisation_mean"] = float(rho.mean())
    out["worker_utilisation_p99"] = float(np.percentile(rho, 99)) if T else 0.0
    out["backlogged_worker_minutes"] = int((Q > 1).sum())
    if detail:
        out["_rho"] = rho; out["_Q"] = Q
        out["_cold_cost"] = cold_cost.reshape(A, R)
        out["_remote_cost"] = remote_cost.reshape(A, N)
        out["_miss_a"] = miss_a; out["_coldmiss_a"] = coldmiss_a; out["_req_a"] = req_a
    return out

# ===== END FILE: tmp/tests/cellsim.py =====

# ===== BEGIN FILE: tmp/tests/hidden_eval.py =====
"""Replays /app/placement_plan.json against the cell's actual traffic for 2026-10-26 .. 11-08 and
writes /logs/verifier/reward.txt and metrics.json. The plan is parsed as data; nothing from /app is
executed or imported."""
import json
import math
import os
import stat
import sys
import time

TESTS = os.environ.get("RLP_TESTS_DIR", os.path.dirname(os.path.abspath(__file__)))
APP = os.environ.get("RLP_APP_DIR", "/app")
LOGS = os.environ.get("RLP_LOG_DIR", "/logs/verifier")
sys.path.insert(0, TESTS)

import numpy as np  # noqa: E402
import cellsim  # noqa: E402

PLAN_NAME = "placement_plan.json"
GROUPS = ["premium_w0", "premium_w1", "standard_w0", "standard_w1"]


def write_out(reward, metrics):
    os.makedirs(LOGS, exist_ok=True)
    for name in ("reward.txt", "metrics.json"):
        p = os.path.join(LOGS, name)
        try:
            if os.path.islink(p) or os.path.exists(p):
                os.unlink(p)
        except OSError:
            pass
    metrics["reward"] = reward
    for name, text in (("metrics.json", json.dumps(metrics, indent=1)), ("reward.txt", f"{reward:.6f}\n")):
        p = os.path.join(LOGS, name)
        fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
        with os.fdopen(fd, "w") as f:
            f.write(text)
    print(f"reward {reward:.6f}")


def read_plan_bytes(path):
    """Open the candidate file without following symlinks or blocking on special files."""
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode):
            raise cellsim.PlanError("plan is not a regular file")
        if st.st_size > cellsim.MAX_PLAN_BYTES:
            raise cellsim.PlanError("plan file too large")
        chunks, total = [], 0
        while True:
            b = os.read(fd, 1 << 20)
            if not b:
                break
            total += len(b)
            if total > cellsim.MAX_PLAN_BYTES:
                raise cellsim.PlanError("plan file too large")
            chunks.append(b)
        return b"".join(chunks)
    finally:
        os.close(fd)


def load_hidden():
    hd = os.path.join(TESTS, "hidden")
    cell = cellsim.Cell.load(os.path.join(hd, "cell.json"))
    with open(os.path.join(hd, "adapters_full.json")) as f:
        H = json.load(f)
    ad = cellsim.Adapters(H["adapter_ids"], H["bytes"], H["prompt_mean"], H["output_mean"],
                          H["premium"], H["batch"], cell)
    allowed = {a for a, r in zip(H["adapter_ids"], H["registered"]) if r}
    with open(os.path.join(hd, "anchors.json")) as f:
        anchors = json.load(f)
    return cell, ad, allowed, anchors


def group_rates(res):
    g = {}
    for p, d in res["periods"].items():
        for tier in ("premium", "standard"):
            g[f"{tier}_w{p}"] = d[tier]["ttft_slo_miss_rate"]
    return g


def reward_from(groups, anchors):
    per = {}
    for g in GROUPS:
        m = max(groups[g], 1e-9)
        m0, m1 = anchors["miss0"][g], anchors["miss1"][g]
        s = math.log(m0 / m) / math.log(m0 / m1)
        per[g] = float(min(1.0, max(0.0, s)))
    return float(sum(anchors["weights"][g] * per[g] for g in GROUPS)), per


def main():
    t0 = time.time()
    metrics = {"version": "0.1"}
    try:
        cell, ad, allowed, anchors = load_hidden()
    except Exception as e:  # environment problem, not the candidate's
        print("failed to load hidden data:", e, file=sys.stderr)
        raise
    path = os.path.join(APP, PLAN_NAME)
    try:
        raw = read_plan_bytes(path)
        try:
            doc = json.loads(raw.decode("utf-8"), parse_constant=lambda c: (_ for _ in ()).throw(
                cellsim.PlanError(f"invalid JSON constant {c}")))
        except (UnicodeDecodeError, ValueError, RecursionError) as e:
            raise cellsim.PlanError(f"plan is not valid JSON: {type(e).__name__}")
        plan = cellsim.parse_plan(doc, ad, cell, allowed=allowed)
        errs = plan.violations(ad, cell)
        if errs:
            raise cellsim.PlanError("; ".join(errs[:5]))
    except FileNotFoundError:
        metrics["status"] = "missing plan"
        return write_out(0.0, metrics)
    except (cellsim.PlanError, OSError) as e:
        metrics["status"] = f"rejected: {str(e)[:300]}"
        return write_out(0.0, metrics)
    z = np.load(os.path.join(TESTS, "hidden", "window_trace.npz"), allow_pickle=False)
    trace = dict(indptr=z["indptr"].astype(np.int64), adapter=z["adapter"].astype(np.int64),
                 count=z["count"].astype(np.int64))
    res = cellsim.simulate(trace, ad, plan, cell, minute0=0)
    groups = group_rates(res)
    reward, per = reward_from(groups, anchors)
    metrics.update(status="ok", miss_rate=groups, group_score=per,
                   adapter_loads=res["adapter_loads"], object_store_loads=res["object_store_loads"],
                   backlogged_worker_minutes=res["backlogged_worker_minutes"],
                   pinned=int(plan.pinned.sum()), staged=int(plan.staged.sum()),
                   planned=int(sum(1 for s in plan.sets if s)), seconds=round(time.time() - t0, 1))
    write_out(reward, metrics)


if __name__ == "__main__":
    main()

# ===== END FILE: tmp/tests/hidden_eval.py =====

