# ===== BEGIN FILE: tmp/tests/test_security.py =====
"""Regression checks for the verifier's handling of untrusted /app contents.

Runs hidden_eval.py against crafted /app directories (via RLP_APP_DIR / RLP_LOG_DIR) and checks
that every malformed or hostile plan is rejected cleanly with reward 0, that nothing outside the
log directory is written, and that /tests is not readable by an unprivileged user once test.sh
has run. Positive control: a valid plan is accepted.

    python3 /tests/test_security.py            (as root, after test.sh)
"""
import json
import os
import shutil
import subprocess
import sys
import tempfile

TESTS = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, TESTS)
EVAL = os.path.join(TESTS, "hidden_eval.py")
H = json.load(open(os.path.join(TESTS, "hidden", "adapters_full.json")))
REG = [a for a, r in zip(H["adapter_ids"], H["registered"]) if r]
UNREG = [a for a, r in zip(H["adapter_ids"], H["registered"]) if not r]
results = []


def run(setup, expect_ok=False, name="", timeout=600):
    root = tempfile.mkdtemp()
    app, logs = os.path.join(root, "app"), os.path.join(root, "logs")
    os.makedirs(app); os.makedirs(logs)
    extra = setup(app, logs) or {}
    env = dict(os.environ, RLP_APP_DIR=app, RLP_LOG_DIR=logs, RLP_TESTS_DIR=TESTS)
    try:
        p = subprocess.run([sys.executable, "-I", EVAL], env=env, capture_output=True, text=True, timeout=timeout)
        rc = p.returncode
    except subprocess.TimeoutExpired:
        rc = "timeout"
    rpath = os.path.join(logs, "reward.txt"); mpath = os.path.join(logs, "metrics.json")
    ok = rc == 0 and os.path.isfile(rpath) and not os.path.islink(rpath)
    reward = float(open(rpath).read()) if ok else None
    status = json.load(open(mpath)).get("status") if ok and os.path.isfile(mpath) else None
    if expect_ok:
        passed = ok and status == "ok"
    else:
        passed = ok and reward == 0.0 and status != "ok"
    for check in extra.get("post", []):
        passed = passed and check()
    results.append((name, passed, rc, reward, status))
    shutil.rmtree(root, ignore_errors=True)


def write(app, obj):
    with open(os.path.join(app, "placement_plan.json"), "w") as f:
        f.write(obj if isinstance(obj, str) else json.dumps(obj))


def entry(a, ws=("n0-g0",), pin=False, stage=False):
    return {"adapter_id": a, "workers": list(ws), "pin_gpu": pin, "stage_host": stage}


# ---------------------------------------------------------------- hostile / malformed inputs
run(lambda a, l: None, name="missing plan")
run(lambda a, l: os.symlink(os.path.join(TESTS, "hidden", "anchors.json"), os.path.join(a, "placement_plan.json")),
    name="symlink to hidden file")
run(lambda a, l: os.mkfifo(os.path.join(a, "placement_plan.json")), name="fifo (must not block)", timeout=120)
run(lambda a, l: os.makedirs(os.path.join(a, "placement_plan.json")), name="directory")
run(lambda a, l: write(a, " " * (33 * 1024 * 1024)), name="oversized file")
run(lambda a, l: write(a, "[" * 200000 + "]" * 200000), name="deep nesting")
run(lambda a, l: write(a, '{"adapters": [{"adapter_id": "%s", "workers": ["n0-g0"], "pin_gpu": NaN}]}' % REG[0]),
    name="NaN constant")
run(lambda a, l: write(a, b"\xff\xfe".decode("latin-1")), name="not utf-8 json")
run(lambda a, l: write(a, {"adapters": [entry("lora-doesnotexist")]}), name="unknown adapter")
run(lambda a, l: write(a, {"adapters": [entry(UNREG[0])]}), name="adapter registered after export")
run(lambda a, l: write(a, {"adapters": [entry(REG[0]), entry(REG[0])]}), name="duplicate adapter")
run(lambda a, l: write(a, {"adapters": [entry(REG[0], ws=("n9-g9",))]}), name="unknown worker")
run(lambda a, l: write(a, {"adapters": [entry(REG[0], ws=("n0-g0", "n0-g0"))]}), name="duplicate worker")
run(lambda a, l: write(a, {"adapters": [dict(entry(REG[0]), pin_gpu=1)]}), name="non-bool pin")
run(lambda a, l: write(a, {"adapters": [entry(x, pin=True) for x in REG]}), name="pinned budget exceeded")
run(lambda a, l: write(a, {"adapters": [entry(x, ws=("n0-g0", "n1-g0"), stage=True) for x in REG]}),
    name="staging budget exceeded")
run(lambda a, l: write(a, {"adapters": "all"}), name="wrong schema")
ALLW = [f"n{n}-g{g}" for n in range(2) for g in range(8)]
run(lambda a, l: write(a, {"adapters": [entry(x, ws=ALLW) for x in REG[:400]]}), name="router table exceeded")


def pre_symlink(a, l):
    victim = os.path.join(os.path.dirname(l), "victim.txt")
    open(victim, "w").write("untouched")
    os.symlink(victim, os.path.join(l, "reward.txt"))
    os.symlink(victim, os.path.join(l, "metrics.json"))
    write(a, {"adapters": []})
    return {"post": [lambda: open(victim).read() == "untouched"]}


results_before = len(results)
run(pre_symlink, expect_ok=True, name="pre-existing symlinks in log dir")

# ---------------------------------------------------------------- positive control
run(lambda a, l: write(a, {"cell": "usw2-c07", "adapters": [entry(REG[0], ws=("n0-g1", "n1-g3"), pin=True, stage=True)]}),
    expect_ok=True, name="valid plan accepted")

# ---------------------------------------------------------------- permissions (Harbor layout only)
if os.geteuid() == 0 and TESTS == "/tests":
    r = subprocess.run(["su", "nobody", "-s", "/bin/sh", "-c", "cat /tests/hidden/anchors.json"],
                       capture_output=True)
    results.append(("/tests unreadable by nobody", r.returncode != 0, r.returncode, None, None))

bad = [r for r in results if not r[1]]
for name, passed, rc, reward, status in results:
    print(f"{'PASS' if passed else 'FAIL'}  {name:42s} rc={rc} reward={reward} status={status}")
print(f"{len(results) - len(bad)}/{len(results)} passed")
sys.exit(1 if bad else 0)

